if (!user) return "";

// 1. Handle Non-Workers immediately
if (!user.IsWorker) {
    return user.IsPayrollAdmin ? "Payroll Admin" : "User";
}

// 2. Base Role for Workers
const baseRole = user.IsPayrollAdmin ? "Payroll Admin" : "Worker";

// 3. Append Position Details
if (user.Department && user.Title) {
    return `${baseRole} | ${user.Department} - ${user.Title}`;
}

// 4. Fallback if no position is assigned
return `${baseRole} | No Position Assigned`;

const userRoles = await $ctrl.workerGridControllerService.loadWorkerGridData($ctrl, {
    entityType: "user_role",
    query: `UserId_eq=${userId}`,
    customEntityKey: "userrole",
    columnDefs: {},
    page: 1,
    limit: $ctrl.tabStore.user_role.limit,
    resetUiState: false,
    touchLoadingStates: false
});

return userRoles ?? [];

const ROLES = {
    worker: 1,
    payrollAdmin: 2
};

const userRoleIds = roleEntities.map(r => r.RoleId);

return {
    IsWorker: userRoleIds.includes(ROLES.worker),
    IsPayrollAdmin: userRoleIds.includes(ROLES.payrollAdmin)
};

// Update the Display Role (e.g., "Worker | HR - Manager")
$ctrl.uiState.displayedRole = $ctrl.helpers._getUserDisplayRole({
    ...roleFlags,
    Department: entity.Department,
    Title: entity.Title,
});

// Merge flags into the selected entity for global access
$ctrl.uiState.selectedEntity = {
    ...entity,
    ...roleFlags
};

// Destructure to separate Worker-specific fields from User fields
const {
    PositionId,
    Position,
    Department,
    Title,
    CustomAnnualRate,
    EmploymentStartDate,
    CreatedDate,
    CreatedBy,
    UpdatedDate,
    UpdatedBy,
    ...userData
} = entity;

// Return the clean User object with Role flags and Audit fields
// return $ctrl.referenceDataService.hydrateEntity({
//     ...userData,
//     ...roleFlags,
//     CreatedDate,
//     CreatedBy,
//     UpdatedDate,
//     UpdatedBy
// });

const baseEntity = {
    ...userData,
    ...roleFlags,
    CreatedDate,
    CreatedBy,
    UpdatedDate,
    UpdatedBy
};

// Temporarily skip hydration for non-admin users (no scope access yet to the lookup
// endpoints hydrateEntity calls). Manually replicate hydrateEntity's resulting shape,
// falling back to raw ids instead of resolved labels — same fallback hydrateEntity
// itself uses when a lookup fails. Remove this branch once new scopes are added.
if (!$ctrl.authService.isCurrentUserAdmin) {
    const fallbackHydrated = { ...baseEntity };

    Object.keys(fallbackHydrated).forEach(key => {
        if (key.endsWith("Id") && key.length > 2) {
            const entityType = key.slice(0, -2);
            const id = fallbackHydrated[key];

            if (entityType.includes("CalculationMethod") && id != null) {
                if (id == 1) fallbackHydrated[entityType] = "FLAT";
                else if (id == 2) fallbackHydrated[entityType] = "PERCENT";
                else fallbackHydrated[entityType] = id;
                return;
            }

            if (entityType === "Worker") return; // handled below

            fallbackHydrated[entityType] = id;
        }
    });

    if (fallbackHydrated.WorkerId != null) {
        fallbackHydrated.Worker = fallbackHydrated.WorkerId;
    }

    return fallbackHydrated;
}

// Return the clean User object with Role flags and Audit fields
return $ctrl.referenceDataService.hydrateEntity(baseEntity);

if (!data) return [];

const detailsList = $ctrl.entityViewService.generateDetailsList(data);

if (tabConfig?.containsSensitiveInfo && tabConfig?.sensitiveInfoFields) {
    return $ctrl.helpers._maskSensitiveInfo(tabConfig.sensitiveInfoFields, detailsList);
}

return detailsList;

const sensitiveFieldsSet = new Set(sensitiveInfoFields);
return detailsList.map(item => {
    if (item.isSpacer || !sensitiveFieldsSet.has(item.originalKey)) {
        return item;
    }

    const strValue = String(item.value || "");
    const maskedValue = "*".repeat(strValue.length);

    return {
        ...item,
        originalValue: item.value,
        value: maskedValue, // Default to maskedValue for sensitive info
        maskedValue: maskedValue,
        isMasked: true
    };
});

const tabConfig = $ctrl.tabConfig[entityType];
const workerId = $ctrl.workerId;

let filtersToProcess = [...($ctrl.uiState.currentFilter.advancedFilters || [])];
let extraApiQuery = "";

let apiQuery = $ctrl.filterService.buildCombinedQuery({
    advancedFilters: filtersToProcess
});

if (tabConfig?.isWorkerBound) {
    apiQuery += workerId ? `&WorkerId_eq=${workerId}` : `&Id_eq=-1`;
}

if (entityType === "worker") {
    apiQuery += workerId ? `&Id_eq=${workerId}` : `&Id_eq=-1`;
}

if (tabConfig?.containsSensitiveInfo) {
    apiQuery += "&maskSensitiveWorkerInfo=false" // Request unmasked data and just do FE masking to reduce API roundtrips
}

return apiQuery + extraApiQuery;

$ctrl.uiState.selectedEntity = null;
$ctrl.uiState.selectedEntityName = "";

$ctrl.uiState.displayedInfo = [];
$ctrl.uiState.detailsList = [];

if (resetTabStore && $ctrl.tabStore[$ctrl.entityType]) {
    $ctrl.tabStore[$ctrl.entityType].data = [];
}

if (!$ctrl.uiState.selectedEntity) {
    console.warn("[_updatePositionData] uiState.selectedEntity is null — skipping position update.");
    return;
}

if (newPosId) {
    const newPosInfo = $ctrl.referenceData.positionMap.find(p => p.Id === newPosId);
    if (newPosInfo) {
        $ctrl.uiState.selectedEntity.PositionId = newPosId;
        $ctrl.uiState.selectedEntity.Department = newPosInfo.Department;
        $ctrl.uiState.selectedEntity.Title = newPosInfo.Title;
        $ctrl.uiState.selectedEntity.CustomAnnualRate = formData.customAnnualRate;
    } else {
        console.warn("[_updatePositionData] Could not find new Position data. This could be caused by data that is loaded from another Company.");
    }
} else {
    $ctrl.uiState.selectedEntity.PositionId = null;
    $ctrl.uiState.selectedEntity.Department = null;
    $ctrl.uiState.selectedEntity.Title = null;
    $ctrl.uiState.selectedEntity.CustomAnnualRate = null;
}

$ctrl.uiState.displayedRole = $ctrl.helpers._getUserDisplayRole($ctrl.uiState.selectedEntity);

if (!form) return {};

const FIELDS_TO_EXCLUDE = [
    "accrualId",            // Update Accrual Balance
    "customAnnualRate",     // Update Worker
    "positionId",           // Update Worker
    "workerId"              // Update Worker
];

const sanitizedForm = { ...form };

FIELDS_TO_EXCLUDE.forEach(field => {
    if (Object.hasOwn(sanitizedForm, field)) {
        delete sanitizedForm[field];
    }
});

return sanitizedForm;

let msg = "Looks like there's no data here. ";

if($ctrl.authService.isCurrentUserAdmin) {
    msg += "Click + to get started.";
}

return msg;

const tabStore = $ctrl.tabStore[entityType];
const tabConfig = $ctrl.tabConfig[entityType];
const { page = tabStore.currentPage, currentRequestId } = params;

try {
    await $ctrl.workerGridControllerService.loadWorkerGridData($ctrl, {
        entityType: entityType,
        query: query,
        columnDefs: tabConfig?.columnDefaultConfig ?? [],
        customEntityKey: tabConfig?.customEntityKey,
        page: page,
        limit: tabStore.limit,
        hydrateOnLoad: false,
        resetUiState: false,
        touchLoadingStates: false,
        reloadColumns: false
    });

    // After Grid Data Load, check if the user switched tabs while the grid was fetching, abort before processing single-record logic
    if (currentRequestId !== $ctrl.uiState.currentRequestId) return;

    if (!tabConfig?.isMultiple && tabStore.data && tabStore.data.length > 0) {
        if (entityType === "user") {
            await $ctrl.loaders.loadAdditionalUserData();
            $ctrl.workerName = $ctrl.uiState.selectedEntityName = $ctrl.tabConfig.user.getName($ctrl.tabStore.user.data[0]);
            $ctrl.uiState.selectedEntity = $ctrl.tabStore.user.data[0];
            return;
        } else {
            const entity = tabStore.data[0];
            if (entityType === "worker") {
                // Fetch fresh positionId and customAnnualRate incase of update
                if ($ctrl.authService.isCurrentUserAdmin) {
                    try {
                        const posRes = await $ctrl.payrollApiService.get({
                            entity: "worker_position",
                            limit: 1,
                            query: `WorkerId_eq=${$ctrl.workerId}`,
                            customEntityKey: "workerposition"
                        });
                        const posRecords = posRes.entities || posRes || [];
                        const posRecord = posRecords[0];

                        entity.PositionId = posRecord?.PositionId ?? null;
                        entity.CustomAnnualRate = posRecord?.CustomAnnualRate ?? null;

                        $ctrl.positionId = entity.PositionId;
                        $ctrl.uiState.customAnnualRate = entity.CustomAnnualRate;
                        $ctrl.uiState.positionLookupFailed = false;
                    } catch (err) {
                        console.error("Failed to fetch worker position data", err);
                        entity.PositionId = $ctrl.positionId ?? null;
                        entity.CustomAnnualRate = $ctrl.uiState.customAnnualRate ?? null;
                    }
                } else {
                    entity.PositionId = $ctrl.positionId;
                    entity.CustomAnnualRate = $ctrl.uiState.customAnnualRate;
                }

            }

            // Temporarily prevent hydration for non admin user
            // Will be removed after new scopes are added
            if ($ctrl.authService.isCurrentUserAdmin) {
                const hydratedEntity = await $ctrl.referenceDataService.hydrateEntity(entity);

                // Check after hydration
                // If user switched tabs while reference data was hydrating, abort before mutating the UI
                if (currentRequestId !== $ctrl.uiState.currentRequestId) return;

                $ctrl.helpers._setDisplayedInfo(hydratedEntity);
                $ctrl.uiState.selectedEntity = hydratedEntity;

                if (entityType === "worker" && $ctrl.userId) {
                    const roleEntities = await $ctrl.helpers._fetchUserRoles($ctrl.userId);
                    if (currentRequestId !== $ctrl.uiState.currentRequestId) return;

                    const roleFlags = $ctrl.helpers._getRoleFlags(roleEntities);
                    const positionId = $ctrl.positionId;
                    const positionInfo = positionId
                        ? $ctrl.referenceData.positionMap.find(p => p.Id === positionId)
                        : null;

                    $ctrl.uiState.displayedRole = $ctrl.helpers._getUserDisplayRole({
                        ...roleFlags,
                        Department: positionInfo?.Department,
                        Title: positionInfo?.Title
                    });

                    $ctrl.workerRole = $ctrl.uiState.displayedRole;
                }
            } else {
                $ctrl.helpers._setDisplayedInfo(entity);
                $ctrl.uiState.selectedEntity = entity;
            }

        }
    }

} finally {
    // Manual loading state reset
    // Only turn off the spinner if this request is still the most recent request
    // If a new request started, let its 'true' state persist so the spinner doesn't flicker
    if (currentRequestId === $ctrl.uiState.currentRequestId) {
        $timeout(() => {
            if (currentRequestId === $ctrl.uiState.currentRequestId) {
                $ctrl.isLoadingTable = false;
            }
        });
    }
}

const roleEntities = await this.helpers._fetchUserRoles($ctrl.uiState.selectedEntity.Id);
const roleFlags = this.helpers._getRoleFlags(roleEntities);
this.helpers._updateProfileState($ctrl.uiState.selectedEntity, roleFlags);
return await this.helpers._buildUserProfileData($ctrl.uiState.selectedEntity, roleFlags);

if (!$ctrl.userId) {
    return;
}

// Close any open panels on load
if ($ctrl.uiState.isEditingTerminationInfo) {
    $ctrl.uiState.isEditingTerminationInfo = false;
}

$ctrl.sidePanelVisible = false;
$ctrl.formManagementService.onFormClose($ctrl.uiState);
$ctrl.isPanelOpen = false;


if (!params) params = {};
$ctrl.uiState.currentTab.name = $ctrl.entityType;
const entityType = $ctrl.entityType;
$ctrl.uiState.currentRequestId++;
const currentRequestId = $ctrl.uiState.currentRequestId;

// Setting it manually here and is reset in loadProfileGridData's finally block if requestId matches
$ctrl.isLoadingTable = true;

if (entityType === "user") {
    const query = `Id=${$ctrl.userId}`;
    params.currentRequestId = currentRequestId;
    await $ctrl.loaders.loadGridData(entityType, query, params);

    // Initial race condition check: Did the user click another tab while waiting?
    if (currentRequestId !== $ctrl.uiState.currentRequestId) return;

    const updatedUserData = $ctrl.tabStore.user.data.find(u => u.Id === $ctrl.uiState.selectedEntity.Id);
    if (updatedUserData) {
        $ctrl.uiState.selectedEntity = updatedUserData;
    }

    const userData = await $ctrl.loaders.loadCompleteUserProfileTab();

    // Check again before mutating the UI state
    if (currentRequestId !== $ctrl.uiState.currentRequestId) return;

    $ctrl.helpers._setDisplayedInfo(userData);
    $ctrl.uiState.selectedEntity = userData;
    $ctrl.workerRole = $ctrl.uiState.displayedRole;
    $ctrl.isWorker = $ctrl.uiState.selectedEntity.IsWorker;
    $ctrl.positionId = $ctrl.tabStore.user.data[0].PositionId;
    $ctrl.uiState.customAnnualRate = $ctrl.tabStore.user.data[0].CustomAnnualRate;

    if($ctrl.links.length === 1) {
        $ctrl.links.push(
            {
                label: $ctrl.uiState.selectedEntityName,
                active: true
            }
        );
    }

    if($ctrl.links[1].label !== $ctrl.uiState.selectedEntityName) {
        $ctrl.links[1].label = $ctrl.uiState.selectedEntityName
    }

    // Reset loading state here since it is handled separately from the rest and matches the current request
    if (currentRequestId === $ctrl.uiState.currentRequestId) {
        $timeout(() => {
            if (currentRequestId === $ctrl.uiState.currentRequestId) {
                $ctrl.isLoadingTable = false;
            }
        });
    }

    return;
}

$ctrl.helpers._resetUiState(true);

if (!$ctrl.isWorker || !$ctrl.workerId) {
    if (currentRequestId === $ctrl.uiState.currentRequestId) {
        $timeout(() => {
            if (currentRequestId === $ctrl.uiState.currentRequestId) {
                $ctrl.isLoadingTable = false;
            }
        });
    }
    return;
}

try {
    const finalQuery = await $ctrl.helpers._buildProfileTabQuery(entityType);
    // Abort if user switched tabs while building the query
    if (currentRequestId !== $ctrl.uiState.currentRequestId) return;

    params.currentRequestId = currentRequestId;
    await $ctrl.loaders.loadGridData(entityType, finalQuery, params);
} catch (err) {
    // Only show the error if user is still on the tab that failed
    if (currentRequestId === $ctrl.uiState.currentRequestId) {
        console.error(err);
        $ctrl.utils.toast(`Failed to load ${entityType} data`, "ERROR");
    }

}

if(!$ctrl.authService.isCurrentUserAdmin) {
    return;
}

const workerIds = $ctrl.tabStore.user.data
    .map(u => u.WorkerId).filter(id => id);

if (!workerIds || workerIds.length === 0) return;

try {
    const workerIdFilter = `WorkerId_in=${workerIds.join(',')}`;
    const [employmentInfoRes, workerPositionRes] = await Promise.all([
        $ctrl.payrollApiService.get({
            entity: "employment_info",
            limit: workerIds.length,
            query: `${workerIdFilter}&select=Id,WorkerId,EmploymentStartDate`,
            customEntityKey: "employmentinfo"
        }),
        $ctrl.payrollApiService.get({
            entity: "worker_position",
            limit: workerIds.length,
            query: `${workerIdFilter}&select=Id,WorkerId,PositionId,CustomAnnualRate`,
            customEntityKey: "workerposition"
        })
    ]);

    const employmentInfos = employmentInfoRes.entities || employmentInfoRes || [];
    const workerPositions = workerPositionRes.entities || workerPositionRes || [];

    $ctrl.tabStore.worker_position.data = workerPositions;

    const positionIds = [...new Set(workerPositions.map(wp => wp.PositionId).filter(id => id))];
    let positions = [];

    if (positionIds.length > 0) {
        const positionRes = await $ctrl.payrollApiService.get({
            entity: "position",
            limit: positionIds.length,
            query: `Id_in=${positionIds.join(',')}&select=Id,Department,Title`
        });
        positions = positionRes.entities || positionRes || [];
    }

    const employmentMap = new Map(employmentInfos.map(ei => [ei.WorkerId, ei]));
    const workerPositionMap = new Map(workerPositions.map(wp => [wp.WorkerId, wp]));
    const positionMap = new Map(positions.map(p => [p.Id, p]));

    $ctrl.tabStore.user.data.forEach(user => {
        if (!user.WorkerId) return;

        const empInfo = employmentMap.get(user.WorkerId);
        if (empInfo) {
            user.EmploymentStartDate = empInfo.EmploymentStartDate;
        }

        const wp = workerPositionMap.get(user.WorkerId);
        if (wp && wp.PositionId) {
            const pos = positionMap.get(wp.PositionId);
            if (pos) {
                user.Title = pos.Title;
                user.Department = pos.Department;
                user.PositionId = pos.Id;
                user.CustomAnnualRate = wp.CustomAnnualRate;
            }
        }
    });

} catch (err) {
    console.error("Failed to load additional user data", err);
    $ctrl.utils.toast("Failed to load complete user profiles", "ERROR");
}

if (rowData.isMasked) {
    rowData.value = rowData.originalValue;
    rowData.isMasked = false;
} else {
    rowData.value = rowData.maskedValue;
    rowData.isMasked = true;
}

const discard = await $ctrl.utils.handleUnsavedChanges($ctrl.isPanelOpen);

if (discard) {
    if($ctrl.uiState.isEditingTerminationInfo) {
        $ctrl.uiState.isEditingTerminationInfo = false;
    }

    $ctrl.sidePanelVisible = false;
    $ctrl.formManagementService.onFormClose($ctrl.uiState);
    $ctrl.isPanelOpen = false;
}

return;

if(!$ctrl.authService.isCurrentUserAdmin) {
    $ctrl.utils.toast("You do not have permission to perform this action.", "ERROR");
    console.error("Forbidden");
    return;
}

if(action === "add") {
    $ctrl.formManagementService.onFormOpen(
        $ctrl.uiState,
        $ctrl[$ctrl.tabConfig[$ctrl.entityType].form],
        "add",
        true
    );

    $ctrl.isPanelOpen = true;
    $ctrl.sidePanelVisible = true;
    return;
}

if(action === "edit") {
    $ctrl.formManagementService.onFormOpen(
        $ctrl.uiState,
        $ctrl[$ctrl.tabConfig[$ctrl.entityType].form],
        "edit",
        undefined,
        $ctrl.uiState.selectedEntity
    );

    $ctrl.isPanelOpen = true;
    $ctrl.sidePanelVisible = true;
    return;   
}

if(!$ctrl.authService.isCurrentUserAdmin) {
    $ctrl.utils.toast("You do not have permission to perform this action.", "ERROR");
    console.error("Forbidden");
    return;
}

$ctrl.formManagementService.onFormOpen(
    $ctrl.uiState,
    $ctrl[$ctrl.tabConfig[$ctrl.entityType].form],
    "edit",
    undefined,
    $ctrl.uiState.selectedEntity
)

$ctrl.uiState.isEditingTerminationInfo = true;
$ctrl.isPanelOpen = true;
$ctrl.sidePanelVisible = true;

if(!$ctrl.authService.isCurrentUserAdmin) {
    $ctrl.utils.toast("You do not have permission to perform this action.", "ERROR");
    console.error("Forbidden");
    return;
}

const config = $ctrl.tabConfig[$ctrl.entityType];
if (!config) {
    console.error("No configuration found for current tab:", $ctrl.entityType);
    return;
}

const isCreate = $ctrl.uiState.isCreatingNewEntity;
const isUpdate = $ctrl.uiState.isEditingExistingEntity;
const entityType = $ctrl.entityType;

const isWorker = entityType === "worker";
const isUser = entityType === "user";

const method = isCreate ? "POST" : "PUT";
const formData = $ctrl[config.form];

let displayName = "Item";
if (config.getName) {
    displayName = config.getName(formData);
} else if (config.entityNameKey) {
    displayName = formData[config.entityNameKey] || "Item";
}

const additionalData = {};
if (isCreate) {
    if (config.isCompanyBound) {
        additionalData.CompanyId = $ctrl.globalSelectedCompany.companyId;
    }

    if (config.isWorkerBound && $ctrl.workerId) {
        additionalData.WorkerId = $ctrl.workerId;
    }

    if (config.isUserBound && $ctrl.userId) {
        additionalData.UserId = $ctrl.userId;
    }
}

$ctrl.uiState.isSaving = true;

await $ctrl.entityOperationsService.executeEntityOperation(
    method,
    (isUpdate || isWorker) ? $ctrl.helpers._excludeFieldsOnSave(formData) : formData,
    async (result) => {
        if (isWorker && isCreate) {
            const newWorkerId = result.data.worker.Id;
            if (newWorkerId) {
                $ctrl.workerId = newWorkerId;
                const userRecordToUpdate = $ctrl.tabStore.user.data.find(u => u.Id === $ctrl.userId);
                if (userRecordToUpdate) {
                    userRecordToUpdate.WorkerId = newWorkerId;
                }
            }
        }

        try {
            if (isUser || isWorker) {
                await $ctrl.handlers.handleSaveSideEffects(
                    $ctrl.entityType,
                    result.data || result,
                    $ctrl.uiState.selectedEntity,
                    formData
                );
            }
        } catch (err) {
            console.error("Side effects failed", err);
            $ctrl.utils.toast("Entity saved, but related data (Roles/Positions) failed to update.", "WARNING");
        }

        if (entityType === "worker") {
            $ctrl.positionId = formData.positionId ?? null;
            $ctrl.uiState.customAnnualRate = formData.customAnnualRate ?? null;
        }

        if (isUpdate) {
            if (entityType === "user") {
                $ctrl.uiState.selectedEntityName = formData.firstName + " " + formData.lastName;
                $ctrl.referenceDataService.clearCache("usersByWorkerId");
            }

            const formToReset = document.querySelector('.form');
            if (formToReset) {
                formToReset.scrollTop = 0;
            }

            await $ctrl.loaders.loadActiveTabContent();

            // Reopen panel
            $ctrl.formManagementService.onFormOpen(
                $ctrl.uiState,
                $ctrl[config.form],
                "edit",
                undefined,
                $ctrl.uiState.selectedEntity
            );

            $ctrl.isPanelOpen = true;
            $ctrl.sidePanelVisible = true;

            if ($ctrl.uiState.isEditingTerminationInfo) {
                $ctrl.uiState.isEditingTerminationInfo = false;
            }
        } else {
            $ctrl.loaders.loadActiveTabContent();
            $ctrl.formManagementService.onFormClose($ctrl.uiState);
            $ctrl.sidePanelVisible = false;
            $ctrl.isPanelOpen = false;
            $ctrl.utils.resetForm(formData);
        }
    },
    null,
    () => {
        $ctrl.uiState.isSaving = false;
    },
    $ctrl.entityType,
    displayName,
    $ctrl.uiState.selectedEntity,
    additionalData
);

if(!$ctrl.authService.isCurrentUserAdmin) {
    $ctrl.utils.toast("You do not have permission to perform this action.", "ERROR");
    console.error("Forbidden");
    return;
}

const entityName = $ctrl.entityType
    ? $ctrl.entityType.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ')
    : "Item";
const entityType = $ctrl.entityType;
const entityToDelete = $ctrl.uiState.selectedEntity;

if (!entityToDelete) return;

await $ctrl.entityOperationsService.confirmDelete(entityToDelete, entityName)
    .then(confirmed => {
        if (!confirmed) return;

        $ctrl.uiState.isDeleting = true;

        return $ctrl.entityOperationsService.executeEntityOperation(
            "DELETE",
            null,
            () => {
                if (entityType === 'worker') {
                    $ctrl.workerId = null;
                    $ctrl.positionId = null;
                    $ctrl.uiState.customAnnualRate = null;
                }

                $ctrl.uiState.selectedEntity = null;
                $ctrl.uiState.selectedEntityName = null;

                if (entityType === 'user') {
                    $ctrl.utils.toast("User deleted successfully.", "SUCCESS");
                    $ctrl.$state.go("people_management");
                    return;
                }

                $ctrl.loaders.loadActiveTabContent();
            },
            null,
            () => {
                $ctrl.uiState.isDeleting = false;
            },
            entityType,
            entityName,
            entityToDelete
        );
    });

const promises = [];
const userRoleData = $ctrl.tabStore['user_role']?.data || [];
const workerPositionData = $ctrl.tabStore['worker_position']?.data || [];

if (entityType === 'user') {
    const userId = savedEntity?.user?.Id ?? $ctrl.uiState.selectedEntity.Id;
    const ROLES = { WORKER: 1, ADMIN: 2 };

    const processRoleChange = async (roleId, shouldHaveRole) => {
        const existingRoleRecord = userRoleData.find(r => r.UserId === userId && r.RoleId === roleId);
        const currentlyHasRole = !!existingRoleRecord;

        if (shouldHaveRole && !currentlyHasRole) {
            return $ctrl.payrollApiService.send('user_role', 'POST', {
                RoleId: roleId,
                UserId: userId
            });
        }

        else if (!shouldHaveRole && currentlyHasRole) {
            return $ctrl.payrollApiService.send(`user_role/${existingRoleRecord.Id}`, 'DELETE');
        }
    };

    promises.push(processRoleChange(ROLES.WORKER, formData.isWorker));
    promises.push(processRoleChange(ROLES.ADMIN, formData.isPayrollAdmin));
}

else if (entityType === 'worker') {
    const workerRecord = savedEntity?.worker;
    const workerId = workerRecord?.Id ?? $ctrl?.workerId;

    if (!$ctrl.uiState.selectedEntity && workerRecord) {
        $ctrl.uiState.selectedEntity = { ...workerRecord };
    }

    const newPosId = formData.positionId;

    let existingPositionRecord = workerPositionData.find(p => p.WorkerId === workerId);

    if (!existingPositionRecord) {
        try {
            const res = await $ctrl.payrollApiService.get({
                entity: "worker_position",
                limit: 1,
                query: `WorkerId_eq=${workerId}`,
                customEntityKey: "workerposition"
            });
            const fetched = res.entities || res || [];
            existingPositionRecord = fetched[0];
        } catch (err) {
            console.error("Failed to fetch existing worker_position record", err);
        }
    }

    const oldPosId = existingPositionRecord?.PositionId;

    if (newPosId && !existingPositionRecord) {
        promises.push($ctrl.payrollApiService.send('worker_position', 'POST', {
            WorkerId: workerId,
            PositionId: newPosId,
            CustomAnnualRate: formData.customAnnualRate
        }));
    } else if (existingPositionRecord && (newPosId !== oldPosId || formData.customAnnualRate !== existingPositionRecord.CustomAnnualRate)) {
        if (newPosId) {
            promises.push($ctrl.payrollApiService.send('worker_position', 'PUT', {
                Id: existingPositionRecord.Id,
                PositionId: newPosId,
                CustomAnnualRate: formData.customAnnualRate
            }));
        } else {
            promises.push($ctrl.payrollApiService.send(`worker_position/${existingPositionRecord.Id}`, 'DELETE'));
        }
    }

    if (promises.length > 0) {
        await Promise.all(promises);
    }

    $ctrl.helpers._updatePositionData(newPosId, formData);
    await $ctrl.loaders.loadAdditionalUserData();

    return;
}

if (promises.length > 0) {
    await Promise.all(promises);
}
